cards.starterCode:
const tunggu = (ms, nilai) => new Promise((res) => setTimeout(() => res(nilai), ms));
function proses() {
  return tunggu(100, "kopi").then((menu) => {
    console.log("Dapat", menu);
    return tunggu(100, menu.toUpperCase());
  }).then((besar) => {
    console.log("Jadi", besar);
    return besar.length;
  });
}
// ubah proses() menjadi async function, lalu cetak hasilnya
proses();

