cards.solution:
const tunggu = (ms, nilai) => new Promise((res) => setTimeout(() => res(nilai), ms));
async function proses() {
  const menu = await tunggu(100, "kopi");
  console.log("Dapat", menu);
  const besar = await tunggu(100, menu.toUpperCase());
  console.log("Jadi", besar);
  return besar.length;
}
console.log("Panjang", await proses());
